/**
 * Generated by `npm run blog:schedule` (scripts/blog-schedule.ts). Don't edit.
 *
 * Every post the scheduler released, with the day it goes live at 00:00 UTC.
 * The dates live in each post's frontmatter; this copy lets pages outside the
 * blog link to a post only once it's live, without loading the posts.
 */
export const BLOG_SCHEDULE: Record<string, string> = {
  "best-reddit-monitoring-tools": "2026-11-06",
  "trackreddit-alternatives": "2026-11-09",
  "rednudge-alternatives": "2026-11-13",
  "f5bot-alternatives-reddit-monitoring": "2026-11-16",
  "syften-alternatives": "2026-11-20",
  "gummysearch-alternatives": "2026-12-01",
};

/** Whether a scheduled post has gone live. */
export function guideIsLive(slug: string, today = new Date().toISOString().slice(0, 10)): boolean {
  const date = BLOG_SCHEDULE[slug];
  return !!date && date <= today;
}
